from scapy.all import sniff, ARP

ip_to_mac = {}

def detect_arp_spoof(packet):
    if packet.haslayer(ARP) and packet[ARP].op == 2:
        real_ip = packet[ARP].psrc
        real_mac = packet[ARP].hwsrc
        if real_ip in ip_to_mac and ip_to_mac[real_ip] != real_mac:
            print(f'[!] ALERT: ARP Spoofing detected! IP {real_ip} changed MAC from {ip_to_mac[real_ip]} to {real_mac}')
        ip_to_mac[real_ip] = real_mac

print('[*] Monitoring ARP traffic for anomalies...')
sniff(filter='arp', prn=detect_arp_spoof, count=10)

