def check_bell_lapatula(user_clearance, obj_classification, operation):
    # 1: Confidential, 2: Secret, 3: Top Secret
    if operation == "read":
        return user_clearance >= obj_classification
    elif operation == "write":
        return user_clearance <= obj_classification
    return False

print(check_bell_lapatula(2, 3, "read")) # False (No Read Up)

class ReferenceMonitor:
    def __init__(self, security_labels):
        self.labels = security_labels # dict of resource: level

    def request_access(self, user_level, resource, action):
        if resource not in self.labels:
            return False
        res_level = self.labels[resource]
        if action == "read":
            return user_level >= res_level
        return user_level == res_level

rm = ReferenceMonitor({"file1": 2})
print(rm.request_access(1, "file1", "read"))
